Given an n × n grid mat[][] of integers where values can be negative, find the maximum sum among all possible k × k subgrids.Examples:Input: k = 3, mat[][] = [[1,2,-1,4],[-8,-3,4,2],[3,8,10,-8],[-4,-1,1,7]]Output: 20Explanation: The 3×3 subgrid [[-3,4,2],[8,10,-8],[-1,1,7]] highlighted in red has the maximum sum of 20.Input: k = 1, mat[][] = [[4]]Output: 4Explanation: Only one 1×1 subgrid exists with sum 4.Try It YourselfTable of Content[Naive Approach] Using Brute Force - O(n^4) Time and O(1) Space[Better Approach] Using 2D Prefix Sum - O(n^2) Time and O(n^2) Space[Expected Approach] Using Sliding Window - O(n^2) Time and O(n) Space[Naive Approach] Using Brute Force - O(n^4) Time and O(1) SpaceTry every possible k×k subgrid by fixing the top-left corner and summing all k×k elements. Track the maximum sum found.For every valid top-left corner (i, j) compute the sum of the k×k subgrid.Update result if current sum is greater than maximum found so far.
            C++

    #include <bits/stdc++.h>
using namespace std;

int maximumSum(vector<vector<int>> &mat, int k)
{
    int n = mat.size();
    int res = INT_MIN;

    // Try every possible top-left corner of k x k subgrid
    for (int i = 0; i <= n - k; i++)
    {
        for (int j = 0; j <= n - k; j++)
        {
            int sum = 0;

            // Compute sum of k x k subgrid
            for (int r = i; r < i + k; r++)
                for (int c = j; c < j + k; c++)
                    sum += mat[r][c];

            res = max(res, sum);
        }
    }
    return res;
}

int main()
{
    vector<vector<int>> mat = {{1, 2, -1, 4}, {-8, -3, 4, 2}, {3, 8, 10, -8}, {-4, -1, 1, 7}};
    cout << maximumSum(mat, 3) << endl;
    return 0;
}


