[Expected Approach] Using Sliding Window - O(n^2) Time and O(n) SpaceInstead of storing a full 2D prefix sum array of size O(n^2), we use a 1D column sum array. For each row we maintain a sliding window of k rows per column. Then we slide a horizontal window of size k over the column sums to get each k×k subgrid sum in O(1).Maintain colSum[j] = sum of k elements in column j ending at current row using a vertical sliding window.Once k rows are in the window slide a horizontal window of size k over colSum to get k×k subgrid sums.Track maximum sum found.
            C++

    #include <bits/stdc++.h>
using namespace std;

int maximumSum(vector<vector<int>> &mat, int k)
{
    int n = mat.size();

    // 1D column sum array — O(n) space
    vector<int> colSum(n, 0);
    int res = INT_MIN;

    for (int i = 0; i < n; i++)
    {

        // Update column sums with new row entering and old row leaving window
        for (int j = 0; j < n; j++)
        {
            colSum[j] += mat[i][j];
            if (i >= k)
                colSum[j] -= mat[i - k][j];
        }

        // Slide horizontal window of size k over colSum
        if (i >= k - 1)
        {
            int windowSum = 0;
            for (int j = 0; j < n; j++)
            {
                windowSum += colSum[j];
                if (j >= k)
                    windowSum -= colSum[j - k];
                if (j >= k - 1)
                    res = max(res, windowSum);
            }
        }
    }
    return res;
}

