{
    vector<vector<int>> mat = {{1, 2, -1, 4}, {-8, -3, 4, 2}, {3, 8, 10, -8}, {-4, -1, 1, 7}};
    cout << maximumSum(mat, 3) << endl;
    return 0;
}


